draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // hospital bed
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(W/2-50, H/2-25, 100, 50);
  ctx.strokeRect(W/2-50, H/2-25, 100, 50);

  // dog
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+25, 25, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fill();

  // dog body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2, H/2+75);
  ctx.stroke();

  // dog legs
  ctx.beginPath();
  ctx.moveTo(W/2-15, H/2+75);
  ctx.lineTo(W/2-15, H/2+100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+15, H/2+75);
  ctx.lineTo(W/2+15, H/2+100);
  ctx.stroke();

  // dog tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+75);
  ctx.lineTo(W/2+25+20*Math.sin(t), H/2+100);
  ctx.stroke();

  // patient
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2-75, H/2-25, 25, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fill();

  // patient body
  ctx.beginPath();
  ctx.moveTo(W/2-75, H/2-25+25);
  ctx.lineTo(W/2-75, H/2-25+50);
  ctx.stroke();

  // patient arms
  ctx.beginPath();
  ctx.moveTo(W/2-75, H/2-25+50);
  ctx.lineTo(W/2-75-20, H/2-25+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-75, H/2-25+50);
  ctx.lineTo(W/2-75+20, H/2-25+70);
  ctx.stroke();

  // patient smile
  ctx.beginPath();
  ctx.arc(W/2-75, H/2-25-10+10*Math.sin(t), 10, 0, Math.PI);
  ctx.stroke();

  ctx.restore();
}
